          }
        ]
      }
    ]
  }
}

#!/usr/bin/env node
'use strict';

// Execution fixture for test-hooks.mjs. The hook shim invokes CLI commands as
// `<cli> hooks <subcommand> ...`; surfacing that subcommand proves telemetry
// was attempted without coupling the host-protocol regression to CLI startup.
const [, , group, subcommand] = process.argv;
if (group !== 'hooks' || !subcommand) process.exit(2);
process.stdout.write(`hook-telemetry:${subcommand}`);

#!/usr/bin/env node
/**
 * ruflo-hook.cjs — cross-platform Node.js port of ruflo-hook.sh (#2132, #2721)
 *
 * The bash shim (ruflo-hook.sh) works on Mac/Linux but fails outright on
 * native Windows: hooks.json wrapped it in `/bin/bash -c '...'`, and
 * `/bin/bash` is not a valid Windows path — Codex/Claude Code report
 * "PreToolUse hook (failed) — exit code 1" on every tool call (#2721).
 *
 * This file is now the ONLY hook implementation `hooks.json` invokes, on
 * every OS (see the `node -e` bootstrap command in ../hooks/hooks.json).
 * It replicates, in pure Node with no shell/jq dependency:
 *   - modify-bash / modify-file  (PreToolUse)  — best-effort CLI call, then
 *     emit `{"permission":"allow"}` for Cursor/Claude compatibility. Codex
 *     plugin hooks are detected by their Codex-specific PLUGIN_ROOT /
 *     PLUGIN_DATA variables, falling back to the `turn_id` field Codex
 *     always includes in the hook event JSON, and intentionally receive
 *     empty stdout: a bare Cursor permission object is not valid Codex
 *     hook JSON and is rejected with "hook returned invalid pre-tool-use
 *     JSON output" (#2816, #2856).
 *   - post-command / post-edit  (PostToolUse)  — parse the hook event JSON
 *     from stdin (no jq), extract the same fields the bash version pulled
 *     with jq, and forward them as CLI flags.
 *   - precompact-manual / precompact-auto  (PreCompact) — static guidance
 *     text, no CLI call at all (matches the bash version's plain echoes).
 *   - session-end  (Stop) — forwarded as-is, same flags as before.
 *
 * Shared behaviour:
 *   1. Prefers a locally installed `ruflo` or `claude-flow` binary.
 *   2. Falls back to `npx --prefer-offline ruflo@latest`.
 *   3. ALWAYS exits 0 — hook subcommands are best-effort telemetry; a
 *      failure must never surface an error or block a turn.
 *   4. Swallows all stdout/stderr from the invoked CLI.
 *
 * Usage: node ruflo-hook.cjs <hook-subcommand>
 *   (invoked via the `node -e` bootstrap in hooks.json, which resolves
 *   this script's path from `process.env.CLAUDE_PLUGIN_ROOT` — no shell
 *   env-var expansion needed, so there is no `${VAR}` vs `%VAR%` split)
 */

'use strict';

const { spawnSync, execSync } = require('child_process');
const fs = require('fs');
const path = require('path');
const os = require('os');
const crypto = require('crypto');

/** Exit 0 unconditionally — hooks must never block a turn */
function done() {
  process.exit(0);
}

/** Check if a binary is available on PATH */
function commandExists(cmd) {
  try {
    const result = execSync(
      process.platform === 'win32' ? `where ${cmd}` : `command -v ${cmd}`,
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }
    );
    return result.trim().length > 0;
  } catch {
    return false;
  }
}

/**
 * Spawn the CLI with the hook subcommand + args, forwarding stdinData.
 * Returns true on success (exit 0), false otherwise. Never throws.
 */
function invokeHook(bin, binArgs, hookSubcommand, hookArgs, stdinData) {
  const args = [...binArgs, 'hooks', hookSubcommand, ...hookArgs];
  // On Windows, shell: true is needed to resolve .cmd/.ps1 shims that npm
  // creates for globally-installed bins (`ruflo`, `claude-flow`, `npx`) —
  // CreateProcess cannot execute those directly. BUT shell:true hands the
  // whole command line to cmd.exe, which re-tokenizes it (no automatic
  // quoting of array elements), corrupting any argument containing spaces
  // or shell metacharacters — e.g. a `post-command` value of "echo hi"
  // silently truncates to "echo", and a heredoc value containing `<<`
  // errors outright. `node` itself is always a real .exe (never a shim),
  // so skip the shell entirely there — CreateProcess gets the argv array
  // verbatim, byte-for-byte, no re-tokenization possible. This covers the
  // common `node <cli.js>` invocation (test harness, npx-resolved runs).
  // A real global `ruflo`/`claude-flow` install still goes through the
  // shim path below and inherits cmd.exe's pre-existing argv-mangling
  // limitation for complex values — not a regression from this change,
  // just not fully solved by it; tracked as a follow-up.
  const useShell = process.platform === 'win32' && bin !== 'node' && bin !== process.execPath;
  // Test-only: RUFLO_HOOK_DEBUG_STDOUT surfaces the invoked CLI's own
  // stdout/stderr instead of swallowing them, so test-hooks.mjs can assert
  // on the CLI's actual recorded value (e.g. catching #1859/#1862-style
  // flag-wiring regressions). Production never sets this — hooks must
  // never leak CLI output into the host (Cursor's PreToolUse contract).
  const debug = process.env.RUFLO_HOOK_DEBUG_STDOUT === '1';
  try {
    const result = spawnSync(bin, args, {
      shell: useShell,
      input: stdinData || '',
      encoding: 'utf8',
      stdio: debug ? ['pipe', 'pipe', 'pipe'] : ['pipe', 'ignore', 'ignore'],
      timeout: 30_000,
    });
    if (debug) {
      if (result.stdout) process.stdout.write(result.stdout);
      if (result.stderr) process.stderr.write(result.stderr);
    }
    return result.status === 0;
  } catch {
    return false;
  }
}

/** Best-effort: try ruflo, then claude-flow, then npx. Never throws. */
function invokeCli(hookSubcommand, hookArgs, stdinData) {
  // Test-only escape hatch: point at a specific local build instead of the
  // commandExists() PATH probe (used by test-hooks.mjs and the plugin-hooks
  // real-command smoke so tests exercise the build under test, not whatever
  // happens to be on the runner's PATH). Space-split — always a simple
  // "node /abs/path/cli.js" invocation in practice, never quoted args.
  const override = process.env.RUFLO_HOOK_CLI_OVERRIDE;
  if (override) {
    const [bin, ...binArgs] = override.split(' ').filter(Boolean);
    invokeHook(bin, binArgs, hookSubcommand, hookArgs, stdinData);
    return;
  }
  if (commandExists('ruflo')) {
    invokeHook('ruflo', [], hookSubcommand, hookArgs, stdinData);
    return;
  }
  if (commandExists('claude-flow')) {
    invokeHook('claude-flow', [], hookSubcommand, hookArgs, stdinData);
    return;
  }
  // SKIP npx when RUFLO_HOOK_SKIP_NPX=1 — used by CI smokes that test the
  // shim's *control flow* without exercising npm install network paths.
  // Without the skip, npx can take 30+s on a cold runner, exceeding a
  // smoke's timeout and producing a spurious failure even though the shim
  // itself works correctly. The bash version doesn't hit this because it
  // backgrounded the work.
  if (process.env.RUFLO_HOOK_SKIP_NPX !== '1') {
    invokeHook('npx', ['--prefer-offline', '--yes', 'ruflo@latest'], hookSubcommand, hookArgs, stdinData);
  }
}

/** Read all of stdin synchronously. Returns '' on any failure (best effort). */
function readStdinRaw() {
  try {
    const chunk = Buffer.alloc(64 * 1024);
    let buf = '';
    let bytesRead;
    while (true) {
      try {
        bytesRead = fs.readSync(0 /* STDIN_FILENO */, chunk, 0, chunk.length, null);
        if (bytesRead === 0) break;
        buf += chunk.slice(0, bytesRead).toString('utf8');
      } catch {
        break;
      }
    }
    return buf;
  } catch {
    return '';
  }
}

/** Parse stdinData as JSON, returning {} on any parse failure. */
function parseEventJson(stdinData) {
  try {
    const trimmed = (stdinData || '').trim();
    return trimmed ? JSON.parse(trimmed) : {};
  } catch {
    return {};
  }
}

/**
 * Project-installed hooks and marketplace-plugin hooks can receive the same
 * event. Claim side-effecting events atomically so post-edit learning and
 * session-end consolidation execute exactly once (#2640).
 */
function claimSideEffectEvent(family, stdinData, event) {
  if (/^(1|true|yes|on)$/i.test(process.env.RUFLO_DISABLE_HOOK_DEDUP || '')) return true;
  try {
    const eventId = event?.tool_use_id || event?.toolUseId ||
      event?.session_id || event?.sessionId || event?.hook_event_id;
    const payloadIdentity = eventId
      ? `event:${eventId}`
      : `payload:${(stdinData || '').trim()}|bucket:${Math.floor(Date.now() / 2000)}`;
    const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
    const digest = crypto.createHash('sha256')
      .update(`ruflo-hook-dedup-v1\0${path.resolve(projectRoot)}\0${family}\0${payloadIdentity}`)
      .digest('hex');
    const dir = process.env.RUFLO_HOOK_DEDUP_DIR ||
      path.join(os.tmpdir(), 'ruflo-hook-dedup-v1');
    fs.mkdirSync(dir, { recursive: true });
    const fd = fs.openSync(path.join(dir, digest), 'wx', 0o600);
    fs.writeFileSync(fd, String(Date.now()));
    fs.closeSync(fd);
    return true;
  } catch (error) {
    return error?.code === 'EEXIST' ? false : true;
  }
}

/**
 * Codex sets PLUGIN_ROOT and PLUGIN_DATA for plugin-bundled hooks, in
 * addition to the cross-host CLAUDE_PLUGIN_* compatibility variables.
 * Cursor and Claude Code use CLAUDE_PLUGIN_ROOT without these Codex-specific
 * variables. Keep this positive Codex check narrow so existing Cursor
 * installations retain their permission response.
 *
 * Fallback: Codex's PreToolUse input JSON always carries a `turn_id` string
 * field (verified against codex-rs' pre-tool-use.command.input schema —
 * it is Codex's own documented extension, not present in Claude Code's or
 * Cursor's hook payloads). This catches any install/config path where the
 * PLUGIN_ROOT/PLUGIN_DATA env vars aren't injected, so a stray Cursor-shaped
 * `{"permission":"allow"}` object never reaches Codex's stricter parser
 * (#2856): Codex's output_parser rejects unknown top-level keys outright
 * and reports "hook returned invalid pre-tool-use JSON output" for any
 * JSON-shaped stdout it can't fit into its schema, whereas empty stdout is
 * treated as no-opinion/implicit-allow with no error.
 */
function isCodexPluginHost(event) {
  if (process.env.PLUGIN_ROOT || process.env.PLUGIN_DATA) return true;
  return typeof event?.turn_id === 'string' && event.turn_id.length > 0;
}

/**
 * PreCompact guidance text — matches the bash `echo` lines verbatim.
 * Not a CLI call at all; pure stdout guidance for the transcript/context.
 */
function precompactManual(event) {
  const custom = typeof event?.custom_instructions === 'string' ? event.custom_instructions : '';
  const lines = [
    '🔄 PreCompact Guidance:',
    '📋 IMPORTANT: Review CLAUDE.md in project root for:',
    '   • 54 available agents and concurrent usage patterns',
    '   • Swarm coordination strategies (hierarchical, mesh, adaptive)',
    '   • SPARC methodology workflows with batchtools optimization',
    '   • Critical concurrent execution rules (GOLDEN RULE: 1 MESSAGE = ALL OPERATIONS)',
  ];
  if (custom) lines.push(`🎯 Custom compact instructions: ${custom}`);
  lines.push('✅ Ready for compact operation');
  process.stdout.write(lines.join('\n') + '\n');
}

function precompactAuto() {
  const lines = [
    '🔄 Auto-Compact Guidance (Context Window Full):',
    '📋 CRITICAL: Before compacting, ensure you understand:',
    '   • All 54 agents available in .claude/agents/ directory',
    '   • Concurrent execution patterns from CLAUDE.md',
    '   • Batchtools optimization for 300% performance gains',
    '   • Swarm coordination strategies for complex tasks',
    '⚡ Apply GOLDEN RULE: Always batch operations in single messages',
    '✅ Auto-compact proceeding with full agent context',
  ];
  process.stdout.write(lines.join('\n') + '\n');
}

function main() {
  const [subcommand] = process.argv.slice(2);
  if (!subcommand) done(); // no subcommand — no-op, same as bash version

  // PreCompact: pure guidance text, no CLI call, no stdin required beyond
  // (optionally) custom_instructions for the manual variant.
  if (subcommand === 'precompact-manual') {
    precompactManual(parseEventJson(readStdinRaw()));
    done();
  }
  if (subcommand === 'precompact-auto') {
    precompactAuto();
    done();
  }

  const stdinData = readStdinRaw();
  const event = parseEventJson(stdinData);

  if ((subcommand === 'post-edit' || subcommand === 'session-end') &&
      !claimSideEffectEvent(subcommand, stdinData, event)) {
    done();
  }

  // PostToolUse: derive CLI flags from the hook event JSON (replaces jq).
  if (subcommand === 'post-command') {
    const cmd = event?.tool_input?.command;
    if (!cmd) done(); // bash version: `[ -z "$CMD" ] && exit 0`
    const exitCode = event?.tool_response?.exit_code ?? 0;
    invokeCli('post-command', ['-c', String(cmd), '-s', String(exitCode === 0), '-e', String(exitCode)], stdinData);
    done();
  }
  if (subcommand === 'post-edit') {
    const file = event?.tool_input?.file_path ?? event?.tool_input?.path;
    if (!file) done(); // bash version: `[ -z "$FILE" ] && exit 0`
    invokeCli('post-edit', ['-f', String(file), '-s', 'true'], stdinData);
    done();
  }

  // PreToolUse: telemetry always runs. Cursor retains its permission verdict;
  // Codex unconditional allow is exit 0 with empty stdout (#2816).
  if (subcommand === 'modify-bash' || subcommand === 'modify-file') {
    invokeCli(subcommand, [], stdinData);
    if (!isCodexPluginHost(event)) {
      process.stdout.write('{"permission":"allow"}');
    }
    done();
  }

  // Stop / session-end and anything else: forward remaining argv unchanged
  // (matches ruflo-hook.sh's generic `ruflo hooks "$@"` passthrough).
  const extraArgs = process.argv.slice(3);
  invokeCli(subcommand, extraArgs, stdinData);
  done();
}

main();

#!/usr/bin/env node
/**
 * Regression guard for ruvnet/ruflo#1863 (and the crash class it represents).
 *
 * #1863: `task status <id>` threw `TypeError: Cannot read properties of
 * undefined (reading 'join')` because the command formatter did
 * `result.dependencies.join(', ')` where `dependencies` is typed
 * `string[]` by the callMCPTool<{...}>() generic but the MCP server can
 * legitimately omit it (older store schema, task with no deps). The TS
 * compiler can't see the risk; only running the command does.
 *
 * This smoke drives a handful of CLI command paths that format MCP
 * responses and asserts none of them crash with an unhandled exception
 * (exit code 1 *with* a TypeError/ReferenceError stack — graceful "not
 * found" errors are fine, only unhandled crashes fail the gate).
 *
 * Each command runs with a 30s per-command timeout. The whole script
 * has a 90s process-level watchdog so CI never hangs.
 */

import { spawnSync } from 'node:child_process';
import { resolve, dirname } from 'node:path';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(process.argv[2] ?? resolve(__dirname, '..', '..', '..'));
const CLI = resolve(REPO_ROOT, 'v3/@claude-flow/cli/bin/cli.js');

if (!existsSync(CLI)) {
  console.error(`FAIL: ${CLI} not found — run \`npm --prefix v3/@claude-flow/cli run build\` first`);
  process.exit(1);
}

let failed = 0;
const fail = (m) => { console.error(`FAIL: ${m}`); failed++; };
const pass = (m) => console.log(`ok: ${m}`);

// 90s process-level watchdog.
const watchdog = setTimeout(() => {
  console.log(`\n[watchdog] cli-no-crash exceeded 90s — exiting clean (CI safety). Checks completed so far stand.`);
  process.exit(failed > 0 ? 1 : 0);
}, 90_000);
watchdog.unref();

const CRASH_RE = /TypeError|ReferenceError|Cannot read propert|is not a function|is not defined|Unhandled|UnhandledPromiseRejection/i;

function runCli(args, label) {
  const r = spawnSync('node', [CLI, ...args], {
    cwd: REPO_ROOT,
    timeout: 30_000,
    encoding: 'utf-8',
    env: { ...process.env, CI: 'true' },
  });
  const out = `${r.stdout ?? ''}\n${r.stderr ?? ''}`;
  if (r.error && r.error.code === 'ETIMEDOUT') {
    console.log(`note: ${label} — timed out after 30s (env-dependent backend); not failing on this`);
    return;
  }
  // A crash is: an exception stack in the output. A graceful error (exit 1
  // with a clean "not found" message and no stack) is acceptable.
  if (CRASH_RE.test(out)) {
    fail(`${label} — command crashed with an unhandled exception:\n${out.split('\n').filter(l => CRASH_RE.test(l)).slice(0, 3).join('\n')}`);
  } else {
    pass(`${label} — no unhandled exception (exit ${r.status})`);
  }
}

// --- #1863 — task create then task status must not crash on a fresh task ---

// Create a task; capture an ID if printed.
const createRes = spawnSync('node', [CLI, 'task', 'create', '-t', 'research', '-d', 'cli-no-crash smoke task'], {
  cwd: REPO_ROOT, timeout: 30_000, encoding: 'utf-8', env: { ...process.env, CI: 'true' },
});
const createOut = `${createRes.stdout ?? ''}\n${createRes.stderr ?? ''}`;
if (CRASH_RE.test(createOut)) {
  fail(`#1863-create — \`task create\` crashed:\n${createOut.split('\n').filter(l => CRASH_RE.test(l)).slice(0, 3).join('\n')}`);
} else {
  pass(`#1863-create — \`task create\` did not crash (exit ${createRes.status})`);
  // Try to extract a task id (formats: "task-...", "Task ... created", uuid-ish)
  const idMatch = createOut.match(/\btask[-_][\w-]+\b/i) || createOut.match(/\b[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\b/i);
  if (idMatch) {
    runCli(['task', 'status', idMatch[0]], `#1863-status — \`task status ${idMatch[0]}\``);
  } else {
    // No ID extracted — fall back to `task list` which also formats the same arrays.
    runCli(['task', 'list'], '#1863-list — `task list` (formats the same arrays)');
  }
}

// --- A few other command formatters that touch MCP-typed arrays ---
runCli(['task', 'list'], 'task list');
runCli(['agent', 'list'], 'agent list');
runCli(['memory', 'list'], 'memory list');
runCli(['swarm', 'status'], 'swarm status');

clearTimeout(watchdog);

if (failed > 0) {
  console.error(`\n${failed} CLI command(s) crashed with an unhandled exception — see above. (#1863 class)`);
  process.exit(1);
}
console.log(`\nall cli-no-crash checks green (#1863 class)`);
process.exit(0);

#!/usr/bin/env node
/**
 * CI guard for ADR-095 G2 — hive-mind consensus transport.
 *
 * Asserts the @claude-flow/swarm package ships a real, pluggable
 * consensus transport (not the implicit single-process EventEmitter):
 *
 *   1. The dist exports ConsensusTransport / LocalTransport / signMessage /
 *      verifyMessage / generateNodeKeyPair (the public surface).
 *   2. LocalTransport behavioral round-trip: send → peer handler → reply.
 *   3. Ed25519 signing is REAL — sign(msg) then verify against the right
 *      pubkey is true, against the wrong pubkey is false, and a tampered
 *      payload fails. (Catches a regression to the old `verifySignature()
 *      → return true` stub.)
 *
 * Static + behavioral; runs in <1s; no network or memory backend.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const REPO_ROOT = resolve(process.argv[2] ?? process.cwd());
const DIST_INDEX = resolve(REPO_ROOT, 'v3/@claude-flow/swarm/dist/consensus/index.js');
const DIST_TRANSPORT = resolve(REPO_ROOT, 'v3/@claude-flow/swarm/dist/consensus/transport.js');

let failed = 0;
const fail = (m) => { console.error(`FAIL: ${m}`); failed++; };
const pass = (m) => console.log(`ok: ${m}`);

for (const p of [DIST_INDEX, DIST_TRANSPORT]) {
  if (!existsSync(p)) {
    fail(`${p} not found — run \`npm --prefix v3/@claude-flow/swarm run build\` first`);
  }
}
if (failed > 0) process.exit(1);

// ---- Stage 1: static — required exports present ----

const indexSrc = readFileSync(DIST_INDEX, 'utf-8');
const transportSrc = readFileSync(DIST_TRANSPORT, 'utf-8');

const REQUIRED_INDEX_EXPORTS = ['LocalTransport', 'LocalTransportRegistry', 'FederationTransport', 'generateNodeKeyPair', 'signMessage', 'verifyMessage', 'messageDigest', 'canonicalizeForSigning'];
for (const name of REQUIRED_INDEX_EXPORTS) {
  if (new RegExp(`\\b${name}\\b`).test(indexSrc) || new RegExp(`export.*\\b${name}\\b`).test(transportSrc)) {
    pass(`G2-export — ${name} present in swarm consensus dist`);
  } else {
    fail(`G2-export-missing — ${name} not exported from swarm consensus dist`);
  }
}

// Negative: the transport must NOT contain a "return true" signature stub.
if (/verifySignature[^]*?return\s+true/.test(transportSrc) || /verifyMessage[^]*?return\s+true\s*;/.test(transportSrc.replace(/return verifyMessage|return cryptoVerify/g, ''))) {
  fail('G2-no-stub-regression — found a `return true` signature stub in transport.js (the #G2 bug). Verification must be real Ed25519.');
} else {
  pass('G2-no-stub — no `return true` signature stub in transport.js');
}

// ---- Stage 2: behavioral — LocalTransport round-trip + real Ed25519 ----

const watchdog = setTimeout(() => {
  console.log(`\n[watchdog] consensus-transport behavioral check exceeded 30s — exiting (static checks above stand)`);
  process.exit(failed > 0 ? 1 : 0);
}, 30_000);
watchdog.unref();

try {
  const m = await import(DIST_INDEX);
  const { LocalTransport, LocalTransportRegistry, generateNodeKeyPair, signMessage, verifyMessage } = m;

  // LocalTransport round-trip
  const reg = new LocalTransportRegistry();
  const a = new LocalTransport('a', { registry: reg });
  const b = new LocalTransport('b', { registry: reg });
  b.onMessage(async (msg) => ({ type: 'reply', from: 'b', to: 'a', payload: { echo: msg.type } }));
  const reply = await a.send('b', { type: 'request-vote', payload: { candidateId: 'a' }, term: 1 });
  if (reply && reply.type === 'reply' && reply.payload?.echo === 'request-vote') {
    pass('G2-local-roundtrip — send → peer handler → reply works');
  } else {
    fail(`G2-local-roundtrip — unexpected reply: ${JSON.stringify(reply)}`);
  }
  await a.close(); await b.close();

  // Real Ed25519 sign/verify
  const kpA = generateNodeKeyPair();
  const kpB = generateNodeKeyPair();
  const msg = { type: 'commit', from: 'a', to: 'b', payload: { digest: 'abc123' }, seq: 1 };
  const sig = signMessage(msg, kpA.privateKeyPem);
  const okRight = verifyMessage({ ...msg, signature: sig }, kpA.publicKeyPem);
  const okWrong = verifyMessage({ ...msg, signature: sig }, kpB.publicKeyPem);
  const okTampered = verifyMessage({ ...msg, payload: { digest: 'evil' }, signature: sig }, kpA.publicKeyPem);
  const okMissing = verifyMessage(msg, kpA.publicKeyPem);
  if (okRight === true && okWrong === false && okTampered === false && okMissing === false) {
    pass('G2-ed25519-real — verify true for right key, false for wrong key / tampered payload / missing sig');
  } else {
    fail(`G2-ed25519-real — verification not behaving correctly: right=${okRight} wrong=${okWrong} tampered=${okTampered} missing=${okMissing}`);
  }
} catch (err) {
  fail(`G2-behavioral — error during probe: ${err?.message ?? err}`);
}

clearTimeout(watchdog);

if (failed > 0) {
  console.error(`\n${failed} ADR-095 G2 transport check(s) failed`);
  process.exit(1);
}
console.log(`\nall ADR-095 G2 consensus-transport checks green`);
process.exit(0);

#!/usr/bin/env node
/**
 * Regression guard for ruvnet/ruflo#1859, #1862, #2721, #2816, #2856.
 *
 * Drives every hook command from `hooks/hooks.json` — PreToolUse,
 * PostToolUse, PreCompact, Stop — with synthetic Claude-Code-style stdin,
 * against a locally built CLI, executed EXACTLY as Claude Code/Codex would
 * run it: `spawnSync(command, { shell: true, ... })`, no bash wrapper of
 * our own. That's the point of this rewrite (#2721) — the old version
 * spawned `bash -c <cmd>` itself, which meant it could never have caught
 * the `/bin/bash` literal breaking on native Windows; `shell: true` uses
 * cmd.exe on Windows and /bin/sh elsewhere, matching the real hook runner.
 *
 * Two env vars steer the shim (see ../scripts/ruflo-hook.cjs) at the build
 * under test instead of whatever's on the runner's PATH:
 *   - CLAUDE_PLUGIN_ROOT       — resolves ruflo-hook.cjs's own path (real
 *                                per-hook-invocation env var, always set)
 *   - RUFLO_HOOK_CLI_OVERRIDE  — bypasses the ruflo/claude-flow/npx PATH
 *                                probe so the test exercises the exact
 *                                flag wiring users hit, pinned to the
 *                                build under test (test-only escape hatch)
 *
 * Asserts:
 *   - Exit code 0 (no parser errors like "Invalid value for --format")
 *   - Output records the *intended* value (the file path / command), not a
 *     stray boolean like "true" — the symptom that #1859 reported
 *   - Cursor PreToolUse hooks emit valid `{"permission":"allow"}` JSON
 *   - Codex PreToolUse hooks exit 0 with empty stdout, while both telemetry
 *     subcommands are still invoked (#2816)
 *   - PostToolUse hooks silently no-op (exit 0, no CLI call) when the
 *     expected field is missing from the event JSON
 *   - Malformed / empty stdin never causes a nonzero exit
 *
 * Usage (from repo root):
 *   node plugins/ruflo-core/scripts/test-hooks.mjs <path-to-cli-binary>
 *
 * Wired into .github/workflows/v3-ci.yml as the `plugin-hooks-smoke` job
 * (windows-latest, macos-latest, ubuntu-latest).
 */

import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { tmpdir } from 'node:os';

const __dirname = dirname(fileURLToPath(import.meta.url));
const PLUGIN_ROOT = join(__dirname, '..');
const HOOKS_JSON = join(PLUGIN_ROOT, 'hooks', 'hooks.json');
const HOOK_RECORDER = join(__dirname, 'fixtures', 'hook-cli-recorder.cjs');

// `cliInvoke` is the literal token-string that should run the CLI — caller
// passes the full thing so this script doesn't need to guess shebangs:
//   - local node script:   "node /abs/path/to/bin/cli.js"
//   - npx fallthrough:     "npx --yes @claude-flow/cli@latest"
const cliInvoke = process.argv[2];
if (!cliInvoke) {
  console.error('Usage: node test-hooks.mjs "<cli-invocation-string>"');
  console.error('Examples:');
  console.error('  node test-hooks.mjs "node $PWD/v3/@claude-flow/cli/bin/cli.js"');
  console.error('  node test-hooks.mjs "npx --yes @claude-flow/cli@latest"');
  process.exit(2);
}

const hooks = JSON.parse(readFileSync(HOOKS_JSON, 'utf8'));

const findHook = (event, matcher) => {
  const list = hooks.hooks?.[event] ?? [];
  const hit = matcher === undefined ? list[0] : list.find(h => h.matcher === matcher);
  if (!hit) throw new Error(`No ${event} hook with matcher=${matcher}`);
  return hit.hooks[0].command;
};

const cmdModifyBash = findHook('PreToolUse', 'Bash');
const cmdModifyFile = findHook('PreToolUse', 'Write|Edit|MultiEdit');
const cmdPostCommand = findHook('PostToolUse', 'Bash');
const cmdPostEdit = findHook('PostToolUse', 'Write|Edit|MultiEdit');
const cmdPrecompactManual = findHook('PreCompact', 'manual');
const cmdPrecompactAuto = findHook('PreCompact', 'auto');
const cmdStop = findHook('Stop', undefined);

let failed = 0;
const cases = [];

const run = (name, cmd, stdin, assertions, options = {}) => {
  const env = {
    ...process.env,
    CLAUDE_PLUGIN_ROOT: PLUGIN_ROOT,
    RUFLO_HOOK_CLI_OVERRIDE: options.cliOverride ?? cliInvoke,
    RUFLO_HOOK_SKIP_NPX: '1',
    ...options.env,
  };
  for (const key of options.unsetEnv ?? []) delete env[key];
  if (options.debug !== false) env.RUFLO_HOOK_DEBUG_STDOUT = '1';
  else delete env.RUFLO_HOOK_DEBUG_STDOUT;

  const r = spawnSync(cmd, {
    shell: true,
    input: stdin,
    encoding: 'utf8',
    env,
    // A clean CI runner may spend more than 15 seconds starting the CLI and
    // policy/memory backends for its first Edit hook. Keep a finite timeout,
    // but allow that measured cold-start path to complete.
    timeout: 30_000,
  });
  const combined = (r.stdout ?? '') + (r.stderr ?? '');
  const errors = [];
  if (r.error) errors.push(`spawn error: ${r.error.message}`);
  if (r.status !== 0) errors.push(`exit ${r.status} (expected 0)`);
  for (const a of assertions) {
    if (a.contains && !combined.includes(a.contains)) errors.push(`missing "${a.contains}" in output`);
    if (a.absent && combined.includes(a.absent)) errors.push(`unexpected "${a.absent}" in output`);
    if (Object.hasOwn(a, 'stdoutEquals') && (r.stdout ?? '') !== a.stdoutEquals) {
      errors.push(`stdout was ${JSON.stringify(r.stdout ?? '')}, expected ${JSON.stringify(a.stdoutEquals)}`);
    }
  }
  if (errors.length === 0) {
    console.log(`ok: ${name}`);
  } else {
    console.error(`FAIL: ${name}`);
    for (const e of errors) console.error(`     - ${e}`);
    if (combined.trim()) {
      console.error('     output:');
      for (const line of combined.split('\n').slice(0, 8)) console.error(`       ${line}`);
    }
    failed++;
  }
  cases.push(name);
};

// --- PreToolUse: modify-bash / modify-file ---
const cursorEnv = { unsetEnv: ['PLUGIN_ROOT', 'PLUGIN_DATA'] };
const codexEnv = {
  env: {
    PLUGIN_ROOT,
    PLUGIN_DATA: join(PLUGIN_ROOT, '.test-data'),
  },
  cliOverride: `${process.execPath} ${HOOK_RECORDER}`,
};

run('Cursor PreToolUse (Bash) emits permission-allow JSON',
  cmdModifyBash,
  '{"tool_input":{"command":"echo hi"}}',
  [{ contains: '{"permission":"allow"}' }],
  cursorEnv);

run('Cursor PreToolUse (Edit) emits permission-allow JSON',
  cmdModifyFile,
  '{"tool_input":{"file_path":"/tmp/foo.ts"}}',
  [{ contains: '{"permission":"allow"}' }],
  cursorEnv);

run('Cursor PreToolUse (Bash) emits permission-allow even with empty stdin',
  cmdModifyBash,
  '',
  [{ contains: '{"permission":"allow"}' }],
  cursorEnv);

run('Cursor PreToolUse (Bash) emits permission-allow even with malformed JSON',
  cmdModifyBash,
  '{not json',
  [{ contains: '{"permission":"allow"}' }],
  cursorEnv);

run('Codex PreToolUse (Bash) exits 0 with empty stdout',
  cmdModifyBash,
  '{"hook_event_name":"PreToolUse","tool_name":"Bash","tool_input":{"command":"echo hi"}}',
  [{ stdoutEquals: '' }],
  { ...codexEnv, debug: false });

run('Codex PreToolUse (Edit) exits 0 with empty stdout',
  cmdModifyFile,
  '{"hook_event_name":"PreToolUse","tool_name":"apply_patch","tool_input":{"command":"*** Begin Patch"}}',
  [{ stdoutEquals: '' }],
  { ...codexEnv, debug: false });

run('Codex PreToolUse (Bash) still invokes telemetry',
  cmdModifyBash,
  '{"hook_event_name":"PreToolUse","tool_name":"Bash","tool_input":{"command":"echo hi"}}',
  [{ contains: 'hook-telemetry:modify-bash' }, { absent: '{"permission":"allow"}' }],
  codexEnv);

run('Codex PreToolUse (Edit) still invokes telemetry',
  cmdModifyFile,
  '{"hook_event_name":"PreToolUse","tool_name":"apply_patch","tool_input":{"command":"*** Begin Patch"}}',
  [{ contains: 'hook-telemetry:modify-file' }, { absent: '{"permission":"allow"}' }],
  codexEnv);

// #2856 — Codex's PLUGIN_ROOT/PLUGIN_DATA env vars may not be present on
// every install/config path; the `turn_id` field Codex always includes in
// the hook event JSON is a documented Codex-only extension and must be
// enough on its own to suppress the Cursor-shaped permission object.
const codexTurnIdOnlyEnv = { unsetEnv: ['PLUGIN_ROOT', 'PLUGIN_DATA'] };

run('Codex PreToolUse (Bash) detected via turn_id alone (no PLUGIN_ROOT/PLUGIN_DATA) exits 0 with empty stdout',
  cmdModifyBash,
  '{"hook_event_name":"PreToolUse","turn_id":"turn_2856","model":"gpt-5.6-sol","tool_name":"Bash","tool_input":{"command":"echo hi"}}',
  [{ stdoutEquals: '' }],
  { ...codexTurnIdOnlyEnv, debug: false });

run('Cursor PreToolUse (Bash) without turn_id still emits permission-allow JSON',
  cmdModifyBash,
  '{"hook_event_name":"PreToolUse","tool_name":"Bash","tool_input":{"command":"echo hi"}}',
  [{ contains: '{"permission":"allow"}' }],
  codexTurnIdOnlyEnv);

// --- PostToolUse: post-edit ---
run('Edit hook records file_path (regression #1859: was "true")',
  cmdPostEdit,
  '{"tool_input":{"file_path":"/tmp/foo.ts"}}',
  [{ contains: '/tmp/foo.ts' }, { absent: 'Recording outcome for: true' }, { absent: 'Invalid value' }]);

run('Edit hook records legacy "path" field',
  cmdPostEdit,
  '{"tool_input":{"path":"/tmp/bar.ts"}}',
  [{ contains: '/tmp/bar.ts' }, { absent: 'Invalid value' }]);

run('Edit hook silently no-ops when no path present',
  cmdPostEdit,
  '{"tool_input":{}}',
  []);

run('Edit hook silently no-ops on malformed JSON',
  cmdPostEdit,
  '{not json',
  []);

// --- PostToolUse: post-command ---
run('Bash hook records simple command',
  cmdPostCommand,
  '{"tool_input":{"command":"echo hi"},"tool_response":{"exit_code":0}}',
  [{ contains: 'echo hi' }, { absent: 'Required option missing' }, { absent: 'Invalid value' }]);

run('Bash hook records multi-line heredoc (regression #1859)',
  cmdPostCommand,
  '{"tool_input":{"command":"cat <<EOF\\nline1\\nline2\\nEOF"},"tool_response":{"exit_code":0}}',
  [{ contains: 'cat <<EOF' }, { absent: 'Required option missing' }]);

run('Bash hook records non-zero exit (distinct from -s value)',
  cmdPostCommand,
  '{"tool_input":{"command":"echo failing-cmd"},"tool_response":{"exit_code":1}}',
  [{ contains: 'echo failing-cmd' }, { absent: 'Recording command outcome: false' }, { absent: 'Recording command outcome: true' }]);

run('Bash hook silently no-ops when no command present',
  cmdPostCommand,
  '{"tool_input":{},"tool_response":{}}',
  []);

run('Bash hook silently no-ops on empty stdin',
  cmdPostCommand,
  '',
  []);

// --- PreCompact: pure guidance text, no CLI call ---
run('PreCompact (manual) prints guidance and includes custom instructions',
  cmdPrecompactManual,
  '{"custom_instructions":"focus on the auth module"}',
  [{ contains: 'PreCompact Guidance' }, { contains: 'focus on the auth module' }]);

run('PreCompact (manual) prints guidance with no custom instructions',
  cmdPrecompactManual,
  '{}',
  [{ contains: 'PreCompact Guidance' }, { absent: 'Custom compact instructions' }]);

run('PreCompact (auto) prints guidance',
  cmdPrecompactAuto,
  '',
  [{ contains: 'Auto-Compact Guidance' }]);

// --- Stop: session-end ---
run('Stop hook runs session-end without error',
  cmdStop,
  '{}',
  [{ absent: 'Required option missing' }, { absent: 'Invalid value' }]);

// #2640 — project settings + marketplace plugin can dispatch the same event.
// The shared atomic claim makes the second side-effecting invocation a no-op.
{
  const dedupDir = mkdtempSync(join(tmpdir(), 'ruflo-hook-dedup-test-'));
  const payload = '{"tool_use_id":"toolu_dedup_2640","tool_input":{"file_path":"/tmp/dedup.ts"}}';
  const env = {
    ...process.env,
    CLAUDE_PLUGIN_ROOT: PLUGIN_ROOT,
    CLAUDE_PROJECT_DIR: PLUGIN_ROOT,
    RUFLO_HOOK_CLI_OVERRIDE: `${process.execPath} ${HOOK_RECORDER}`,
    RUFLO_HOOK_DEBUG_STDOUT: '1',
    RUFLO_HOOK_SKIP_NPX: '1',
    RUFLO_HOOK_DEDUP_DIR: dedupDir,
  };
  try {
    const first = spawnSync(cmdPostEdit, { shell: true, input: payload, encoding: 'utf8', env });
    const second = spawnSync(cmdPostEdit, { shell: true, input: payload, encoding: 'utf8', env });
    const ok = first.status === 0 && second.status === 0 &&
      (first.stdout || '').includes('hook-telemetry:post-edit') &&
      !(second.stdout || '').includes('hook-telemetry:post-edit');
    if (ok) {
      console.log('ok: duplicate post-edit event executes side effects exactly once');
    } else {
      console.error('FAIL: duplicate post-edit event was not deduplicated');
      failed++;
    }
    cases.push('duplicate post-edit event executes side effects exactly once');
  } finally {
    rmSync(dedupDir, { recursive: true, force: true });
  }
}

console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed === 0 ? 0 : 1);

#!/usr/bin/env node
/**
 * Regression guard for ruvnet/ruflo#1874.
 *
 * Static dist scan: assert the MCP server packages emit a spec-compliant
 * `YYYY-MM-DD` string for `protocolVersion`, never the previous
 * `{major,minor,patch}` object form. This catches the regression class
 * without needing to actually boot the HTTP server (which has its own
 * separate plumbing issues — bin/cli.js auto-detects MCP-stdio mode for
 * any `mcp start *` invocation when stdin isn't a TTY, and the
 * in-process HTTP server doesn't keep the process alive after start).
 *
 * Combined with:
 *   - witness markers (#1874-mcp, #1874-shared) — manifest attests the
 *     spec strings are present
 *   - corrected unit test in mcp.test.ts — uses the spec string form
 *
 * This three-way coverage catches the bug class.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const REPO_ROOT = resolve(process.argv[2] ?? process.cwd());
const TARGETS = [
  'v3/@claude-flow/mcp/dist/server.js',
  'v3/@claude-flow/shared/dist/mcp/server.js',
];

const SPEC_DATE_REGEX = /^['"]\d{4}-\d{2}-\d{2}['"]$/;
const BAD_OBJECT_REGEX = /protocolVersion\s*=\s*\{\s*major:/;

let failed = 0;
const fail = (m) => { console.error(`FAIL: ${m}`); failed++; };
const pass = (m) => console.log(`ok: ${m}`);

for (const target of TARGETS) {
  const path = resolve(REPO_ROOT, target);
  if (!existsSync(path)) {
    fail(`${target} not found — build the package first`);
    continue;
  }
  const src = readFileSync(path, 'utf8');

  // Reject the buggy object form
  if (BAD_OBJECT_REGEX.test(src)) {
    fail(`${target} contains protocolVersion = {major,...} object (#1874 regression)`);
    continue;
  }

  // Find the protocolVersion assignment and assert it's a date string
  const match = src.match(/protocolVersion\s*=\s*(['"][^'"]*['"]|\{[^}]+\}|[^;,\n]+)/);
  if (!match) {
    fail(`${target} has no protocolVersion assignment — schema changed?`);
    continue;
  }
  const value = match[1].trim();
  if (!SPEC_DATE_REGEX.test(value)) {
    fail(`${target} protocolVersion = ${value} is not a YYYY-MM-DD spec string`);
    continue;
  }
  pass(`${target}: protocolVersion = ${value}`);
}

console.log(failed === 0 ? '\nMCP protocol-shape compliance ✓' : `\n${failed} compliance failure(s) ✗`);
process.exit(failed > 0 ? 1 : 0);

#!/usr/bin/env node
/**
 * Regression guard for ruvnet/ruflo#1889.
 *
 * Tests the round-trip contract between PAIRED MCP tools — tools that
 * write and read from a shared substrate. Each pair must satisfy:
 *
 *   storeTool(X) → MUST be findable via searchTool(matching query)
 *
 * The class of bug #1889 named: the two tools work in isolation but
 * use different controllers, so the write goes to controller A and
 * the search reads controller B. No single-tool test catches this.
 *
 * STRUCTURE:
 *   1. Static dist-scan FIRST — the durable contract. Always completes.
 *   2. Behavioral round-trip SECOND — advisory. Runs with a hard process-
 *      level watchdog so a hanging memory backend can't hang CI.
 *
 * The dist-scan check is the hard gate; behavioral is informational.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';

const REPO_ROOT = resolve(process.argv[2] ?? process.cwd());
const DIST = resolve(REPO_ROOT, 'v3/@claude-flow/cli/dist/src/mcp-tools/agentdb-tools.js');

if (!existsSync(DIST)) {
  console.error(`FAIL: ${DIST} not found — run \`npm --prefix v3/@claude-flow/cli run build\` first`);
  process.exit(1);
}

let failed = 0;
const fail = (m) => { console.error(`FAIL: ${m}`); failed++; };
const pass = (m) => console.log(`ok: ${m}`);

// ===== STAGE 1 — Static dist scan (durable contract; always runs) =====

const distSrc = readFileSync(DIST, 'utf-8');

if (!distSrc.includes("controller: 'memory-store-fallback'")) {
  fail('#1889-store-fallback-missing — agentdb_pattern-store no longer has the memory-store-fallback path');
} else {
  pass('#1889-store-fallback — memory-store-fallback path present in dist');
}

if (!/searchEntries.*pattern|searchEntries\(\{.*namespace: 'pattern'/s.test(distSrc)) {
  fail('#1889-search-fallback-missing — agentdb_pattern-search lacks the symmetric fallback reading from the pattern namespace');
} else {
  pass('#1889-search-fallback — symmetric fallback present in dist');
}

// Final dist-scan: both tools must be exported. Catches refactors that
// drop one half of the pair.
if (!distSrc.includes("name: 'agentdb_pattern-store'") || !distSrc.includes("name: 'agentdb_pattern-search'")) {
  fail('#1889-tools-missing — agentdb_pattern-store and/or agentdb_pattern-search not declared in dist');
} else {
  pass('#1889-tools-present — both pattern-store and pattern-search MCP tool defs present');
}

// If dist-scan failed, bail before the slow behavioral probe.
if (failed > 0) {
  console.error(`\n${failed} dist-scan check(s) failed for #1889 — behavioral probe skipped`);
  process.exit(1);
}

// ===== STAGE 2 — Behavioral round-trip (advisory; process-level watchdog) =====

// Hard watchdog: if the script is still alive after 60s past this point,
// SIGKILL ourselves with a clean message. Prevents a hanging memory backend
// from hanging CI. The dist-scan checks above have already validated the
// durable contract.
const STAGE2_WATCHDOG_MS = 60_000;
const watchdog = setTimeout(() => {
  console.log(`\n[watchdog] behavioral round-trip exceeded ${STAGE2_WATCHDOG_MS}ms — exiting clean. Dist-scan checks above are the durable contract.`);
  console.log(`all #1889 dist-scan checks green (behavioral probe inconclusive — env-dependent)`);
  process.exit(0);
}, STAGE2_WATCHDOG_MS);
watchdog.unref();

try {
  const tools = await import(DIST);
  const TOOLS = Object.fromEntries(
    Object.values(tools)
      .filter(t => t && typeof t === 'object' && typeof t.name === 'string' && typeof t.handler === 'function')
      .map(t => [t.name, t]),
  );

  const withInnerTimeout = (p, ms, label) => Promise.race([
    p,
    new Promise((_, rej) => setTimeout(() => rej(new Error(`inner-timeout ${ms}ms: ${label}`)), ms)),
  ]);

  const sentinel = `roundtrip-sentinel-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

  let storeRes;
  try {
    storeRes = await withInnerTimeout(TOOLS['agentdb_pattern-store'].handler({
      pattern: `Round-trip test sentinel: ${sentinel}. This pattern should be findable via search.`,
      type: 'roundtrip-test',
      confidence: 0.95,
    }), 25_000, 'pattern-store');
  } catch (e) {
    console.log(`note: behavioral round-trip — store timed out (${e.message})`);
    storeRes = null;
  }

  if (storeRes && storeRes.success === true) {
    console.log(`note: behavioral — store succeeded via controller=${storeRes.controller}`);
    await new Promise(r => setTimeout(r, 50));

    let searchRes;
    try {
      searchRes = await withInnerTimeout(TOOLS['agentdb_pattern-search'].handler({
        query: sentinel,
        topK: 5,
        minConfidence: 0,
      }), 25_000, 'pattern-search');
    } catch (e) {
      console.log(`note: behavioral round-trip — search timed out (${e.message})`);
      searchRes = null;
    }

    if (searchRes && Array.isArray(searchRes.results)) {
      const hit = searchRes.results.some(r => JSON.stringify(r).includes(sentinel));
      if (hit) {
        console.log(`note: behavioral — search found sentinel (store=${storeRes.controller}, search=${searchRes.controller}, results=${searchRes.results.length})`);
      } else {
        console.log(`note: behavioral — search returned ${searchRes.results.length} results, sentinel not present. Store=${storeRes.controller}, search=${searchRes.controller}. Likely env memory-db state; dist-scan above is the gate.`);
      }
    }
  } else if (storeRes) {
    console.log(`note: behavioral — store reported non-success: ${JSON.stringify(storeRes).slice(0, 200)}`);
  }
} catch (err) {
  console.log(`note: behavioral — error during probe: ${err?.message ?? err}`);
}

clearTimeout(watchdog);
console.log(`\nall #1889 dist-scan checks green`);
process.exit(0);

#!/usr/bin/env node
/**
 * Regression guard for ruvnet/ruflo#1883 + #1884.
 *
 * #1883 — memory_import_claude `allProjects=false` failed under WSL because
 *         project-hash derivation only POSIX-slash-replaced cwd. We now try
 *         multiple candidate hashes (POSIX, WSL-translated `/mnt/<d>/` →
 *         `<D>-...`, leading-dash-stripped, space-replaced) and accept an
 *         explicit `projectPath` override.
 *
 * #1884 — keys produced by memory_import_claude included raw frontmatter
 *         names + section titles, which could contain shell-metacharacters
 *         in validateMemoryInput's dangerous-pattern set. memory_delete then
 *         rejected those keys, stranding them. We now sanitize at write-time
 *         via sanitizeMemoryKey.
 *
 * This script does three things:
 *   1. Static dist scan — assert sanitizeMemoryKey + resolveProjectMemoryDir
 *      are present in dist and called from the import handler. Catches
 *      regressions where the helpers exist but stop being called.
 *   2. Property check — for every char in DANGEROUS_KEY_CHARS, sanitize and
 *      assert the result passes validateMemoryInput's regex. Proves the
 *      write-path → delete-path round-trip can never strand a key again.
 *   3. WSL-fixture check — feed a synthetic `/mnt/c/Users/x/Project Name`
 *      through resolveProjectMemoryDir's candidate generator and assert the
 *      Claude-Code Windows hash form is among the candidates.
 *
 * Combined with witness markers (#1883-cli, #1884-cli) — which attest that
 * the marker substrings are present in dist — this is the three-way coverage
 * (#1874 pattern: dist scan + behavioral + cryptographic) that gates these
 * regressions.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const REPO_ROOT = resolve(process.argv[2] ?? process.cwd());
const DIST = resolve(REPO_ROOT, 'v3/@claude-flow/cli/dist/src/mcp-tools/memory-tools.js');

let failed = 0;
const fail = (m) => { console.error(`FAIL: ${m}`); failed++; };
const pass = (m) => console.log(`ok: ${m}`);

if (!existsSync(DIST)) {
  fail(`${DIST} not found — run \`npm --prefix v3/@claude-flow/cli run build\` first`);
  process.exit(1);
}
const distSrc = readFileSync(DIST, 'utf-8');

// ---------- 1. Static dist scan ----------

const requiredMarkers = [
  // #1884 — sanitizer helper present and called from the two storeEntry sites
  { id: '#1884-helper-defined', re: /function sanitizeMemoryKey\s*\(/, hint: 'sanitizeMemoryKey() must be defined in dist' },
  { id: '#1884-call-site-1', re: /sanitizeMemoryKey\(`claude:\$\{memFile\.project\}:\$\{name\}`\)/, hint: 'first storeEntry import-key must go through sanitizeMemoryKey' },
  { id: '#1884-call-site-2', re: /sanitizeMemoryKey\(`claude:\$\{memFile\.project\}:\$\{name\}:\$\{sectionTitle\.slice\(0,\s*50\)\}`\)/, hint: 'second (sectioned) storeEntry import-key must go through sanitizeMemoryKey' },

  // #1883 — multi-candidate resolver present, WSL branch present, override plumbed
  { id: '#1883-resolver-defined', re: /function resolveProjectMemoryDir\s*\(/, hint: 'resolveProjectMemoryDir() must be defined in dist' },
  { id: '#1883-wsl-branch', re: /\/\^\\\/mnt\\\/\(\[a-z\]\)\(\\\/\.\*\)\?\$\/i/, hint: 'WSL /mnt/<drive>/ regex must be present in dist' },
  { id: '#1883-override-input', re: /projectPathOverride\s*=\s*input\.projectPath/, hint: 'memory_import_claude must read projectPath from input' },
  { id: '#1883-resolver-call', re: /resolveProjectMemoryDir\(claudeProjectsDir,\s*projectPathOverride\)/, hint: 'import handler must call resolveProjectMemoryDir' },
];

for (const marker of requiredMarkers) {
  if (marker.re.test(distSrc)) pass(`${marker.id} — dist contains required code`);
  else fail(`${marker.id} — ${marker.hint}`);
}

// Negative-attestation: the legacy single-line POSIX hash logic should be gone.
// `cwd.replace(/\//g, '-')` was the entire normalization before #1883.
const legacy = /const projectHash = cwd\.replace\(\/\\\/\/g,\s*['"]-['"]\);/;
if (legacy.test(distSrc)) {
  fail('#1883-regression — legacy single-line POSIX-only hash logic is back; resolveProjectMemoryDir was removed or bypassed');
} else {
  pass('#1883-no-regression — legacy POSIX-only normalization no longer present in dist');
}

// ---------- 2. Property check: sanitizer round-trips through validator ----------
//
// Use the same regex literal as the dist — DANGEROUS_KEY_CHARS / _PATTERN
// share their pattern, so the property test can use one source of truth that
// matches what shipped (the static-scan section above asserts the dist still
// declares them).

const dangerousChars = /[;&|`$(){}[\]<>!#\\\0]|\.\.[/\\]/g;
const dangerousPattern = /[;&|`$(){}[\]<>!#\\\0]|\.\.[/\\]/;

// Confirm the dist literal we're mirroring is byte-identical to what we declare here.
const distRegexLine = '/[;&|`$(){}[\\]<>!#\\\\\\0]|\\.\\.[/\\\\]/';
if (!distSrc.includes('const DANGEROUS_KEY_CHARS = /[;&|`$(){}[\\]<>!#\\\\\\0]|\\.\\.[/\\\\]/g;')) {
  fail('#1884-regex-mirror — DANGEROUS_KEY_CHARS literal in dist no longer matches the test mirror; update both together');
} else {
  pass('#1884-regex-mirror — DANGEROUS_KEY_CHARS literal in dist matches test mirror');
}

// Mimic sanitizeMemoryKey
const sanitize = (k) => k.replace(dangerousChars, '_').slice(0, 1024);

// Property: every char in the dangerous set, embedded in a realistic import
// key, must produce a sanitized key that passes the delete-path validator.
const dangerousSamples = [
  ';', '&', '|', '`', '$', '(', ')', '{', '}', '[', ']',
  '<', '>', '!', '#', '\\', '\0', '../', '..\\',
];
// Realistic markdown-section-shaped strings
const realistic = [
  'Foo (bar)!',
  'Section #1',
  'A & B',
  '${malicious}',
  '`shell`',
  '../etc/passwd',
  'name<tag>value',
  'list[0]',
];

let propFail = 0;
for (const sample of [...dangerousSamples, ...realistic]) {
  const importKey = `claude:project:name:${sample}`;
  const sanitized = sanitize(importKey);
  if (dangerousPattern.test(sanitized)) {
    console.error(`  property fail: sanitize(${JSON.stringify(importKey)}) = ${JSON.stringify(sanitized)} still matches DANGEROUS_KEY_PATTERN`);
    propFail++;
  }
}
if (propFail === 0) pass(`#1884-property — sanitizer output passes validator for ${dangerousSamples.length + realistic.length} adversarial inputs`);
else fail(`#1884-property — ${propFail} sanitized key(s) still rejected by validator`);

// ---------- 3. WSL fixture check ----------
//
// Replicate the candidate-generation loop with a synthetic WSL cwd and
// assert the Claude-Code Windows hash form is among the candidates.

function deriveCandidates(source) {
  const candidates = new Set();
  candidates.add(source.replace(/\//g, '-'));
  const wsl = source.match(/^\/mnt\/([a-z])(\/.*)?$/i);
  if (wsl) {
    const drive = wsl[1].toUpperCase();
    const rest = (wsl[2] ?? '').replace(/\//g, '-').replace(/ /g, '-');
    candidates.add(`${drive}-${rest}`);
  }
  candidates.add(source.replace(/\//g, '-').replace(/^-+/, ''));
  candidates.add(source.replace(/\//g, '-').replace(/ /g, '-'));
  return candidates;
}

const wslCwd = '/mnt/c/Users/tobia/OneDrive/Desktop/Claude Stuff';
const candidates = deriveCandidates(wslCwd);
const expectedWindowsHash = 'C--Users-tobia-OneDrive-Desktop-Claude-Stuff';
if (candidates.has(expectedWindowsHash)) {
  pass(`#1883-wsl-fixture — candidate set includes Claude-Code Windows hash for ${wslCwd}`);
} else {
  fail(`#1883-wsl-fixture — expected ${expectedWindowsHash} in candidate set, got: ${[...candidates].join(' | ')}`);
}

// macOS/Linux POSIX cwd should still produce the legacy hash in candidate set
// so existing-deployment compatibility holds.
const posixCwd = '/Users/alice/projects/ruflo';
const posixCandidates = deriveCandidates(posixCwd);
if (posixCandidates.has('-Users-alice-projects-ruflo')) {
  pass(`#1883-posix-compat — legacy POSIX hash still in candidate set for ${posixCwd}`);
} else {
  fail(`#1883-posix-compat — legacy POSIX hash missing from candidate set; would break existing macOS/Linux installs`);
}

// ---------- Summary ----------
if (failed > 0) {
  console.error(`\n${failed} regression check(s) failed for #1883/#1884`);
  process.exit(1);
}
console.log('\nall #1883/#1884 regression guards green');

#!/usr/bin/env node
/**
 * Query the witness temporal history (ADR-103).
 *
 * Usage:
 *   node history.mjs --history <path> <command> [--id <fixId>] [--json]
 *
 * Commands:
 *   summary       Latest snapshot vs. previous (transitions in/out of pass).
 *   regressions   For each currently-regressed fix, show the commit
 *                 that introduced the regression (last pass → first fail).
 *   timeline      Status timeline for a single fix (--id required).
 *   list          Show all snapshots (commit, issuedAt, summary).
 *
 * Options:
 *   --history <path>  JSONL history file (defaults to ./verification-history.jsonl).
 *   --id <fixId>      Fix id (e.g. F1, #1867) — required for `timeline`.
 *   --json            Machine-readable output.
 */

import { resolve } from 'node:path';
import { existsSync } from 'node:fs';
import { loadHistory, findRegressionIntroductions, fixTimeline, diffLatest } from './lib.mjs';

const args = parseArgs(process.argv.slice(2));
const cmd = args._[0];
const historyPath = resolve(args.history ?? 'verification-history.jsonl');
const asJson = !!args.json;

if (!cmd || args.help) {
  console.error('Usage: history.mjs --history <path> <summary|regressions|timeline|list> [--id X] [--json]');
  process.exit(args.help ? 0 : 2);
}

if (!existsSync(historyPath)) {
  if (asJson) console.log(JSON.stringify({ ok: false, error: `history file not found: ${historyPath}` }));
  else console.error(`history file not found: ${historyPath}`);
  process.exit(1);
}

const history = loadHistory(historyPath);

if (cmd === 'list') {
  if (asJson) {
    console.log(JSON.stringify(history.map(e => ({ commit: e.commit, issuedAt: e.issuedAt, summary: e.summary })), null, 2));
  } else {
    for (const e of history) {
      const s = e.summary;
      console.log(`${e.issuedAt}  ${e.commit.slice(0,12)}  total=${s.totalFixes} verified=${s.verified} missing=${s.missing}`);
    }
  }
  process.exit(0);
}

if (cmd === 'summary') {
  const d = diffLatest(history);
  const out = { entries: history.length, ...d };
  if (asJson) console.log(JSON.stringify(out, null, 2));
  else {
    console.log(`history entries: ${history.length}`);
    console.log(`newly regressed: ${d.newlyRegressed.length ? d.newlyRegressed.join(', ') : '(none)'}`);
    console.log(`newly passing:   ${d.newlyPassing.length ? d.newlyPassing.join(', ') : '(none)'}`);
    console.log(`fixes added:     ${d.added.length ? d.added.join(', ') : '(none)'}`);
    console.log(`fixes removed:   ${d.removed.length ? d.removed.join(', ') : '(none)'}`);
  }
  process.exit(d.newlyRegressed.length > 0 ? 1 : 0);
}

if (cmd === 'regressions') {
  const r = findRegressionIntroductions(history);
  if (asJson) console.log(JSON.stringify(r, null, 2));
  else if (r.length === 0) console.log('no regressed fixes in latest snapshot');
  else for (const x of r) {
    console.log(`${x.id}`);
    console.log(`  last pass:    ${x.lastPassCommit?.slice(0,12) ?? '(never)'}  ${x.lastPassIssuedAt ?? ''}`);
    console.log(`  regressed at: ${x.regressedAtCommit.slice(0,12)}  ${x.regressedAtIssuedAt}`);
  }
  process.exit(r.length > 0 ? 1 : 0);
}

if (cmd === 'timeline') {
  if (!args.id) { console.error('--id <fixId> is required for timeline'); process.exit(2); }
  const t = fixTimeline(history, args.id);
  if (asJson) console.log(JSON.stringify(t, null, 2));
  else for (const e of t) console.log(`${e.issuedAt}  ${e.commit.slice(0,12)}  ${e.status}`);
  process.exit(0);
}

console.error(`unknown command: ${cmd}`);
process.exit(2);

function parseArgs(argv) {
  const out = { _: [] };
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json' || a === '--help') { out[a.slice(2)] = true; continue; }
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else { out[key] = true; }
    } else { out._.push(a); }
  }
  return out;
}

#!/usr/bin/env node
/**
 * Bootstrap a witness manifest in any project (ADR-103).
 *
 * Creates an empty `verification.md.json` and `verification-history.jsonl`
 * at the project root, plus a stub `witness-fixes.json` template that
 * users edit to register their own fix entries.
 *
 * Usage:
 *   node init.mjs [--root <path>]
 */

import { writeFileSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';

const args = parseArgs(process.argv.slice(2));
const root = resolve(args.root ?? process.cwd());

const manifestPath = join(root, 'verification.md.json');
const historyPath = join(root, 'verification-history.jsonl');
const fixesTemplate = join(root, 'witness-fixes.json');

if (existsSync(manifestPath) && !args.force) {
  console.error(`refusing to overwrite ${manifestPath} — pass --force to recreate`);
  process.exit(1);
}

const emptyWitness = {
  manifest: {
    schema: 'ruflo-witness/v1',
    issuedAt: new Date().toISOString(),
    gitCommit: '',
    branch: '',
    releases: {},
    summary: { totalFixes: 0, verified: 0, missing: 0 },
    fixes: [],
  },
  integrity: {
    manifestHashAlgo: 'sha256',
    manifestHash: '',
    signatureAlgo: 'ed25519',
    publicKey: '',
    signature: '',
    seedDerivation: "sha256(gitCommit + ':ruflo-witness/v1')",
  },
};

writeFileSync(manifestPath, JSON.stringify(emptyWitness, null, 2));
writeFileSync(historyPath, '');
writeFileSync(fixesTemplate, JSON.stringify({
  fixes: [
    {
      id: 'EXAMPLE-1',
      desc: 'Replace this with your fix description',
      file: 'src/path/to/fixed-file.ts',
      marker: 'distinctive substring proving the fix is in the file',
    },
  ],
}, null, 2));

console.log(`created:`);
console.log(`  ${manifestPath}`);
console.log(`  ${historyPath}`);
console.log(`  ${fixesTemplate}     (edit then re-run regen)`);
console.log(``);
console.log(`next: install @noble/ed25519, edit witness-fixes.json, then:`);
console.log(`  node /path/to/regen.mjs --manifest verification.md.json \\`);
console.log(`                          --history verification-history.jsonl \\`);
console.log(`                          --fixes witness-fixes.json`);

function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else { out[key] = true; }
    }
  }
  return out;
}

/**
 * Witness library — shared logic for regenerating, verifying, and
 * querying cryptographically-signed fix manifests with temporal
 * history (ADR-103).
 *
 * Pure functions + small I/O helpers; no project-specific assumptions.
 * CLI wrappers in this directory configure paths and surface output.
 *
 * @module plugins/ruflo-core/scripts/witness/lib
 */

import { readFileSync, writeFileSync, existsSync, appendFileSync } from 'node:fs';
import { join } from 'node:path';
import { execSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createRequire } from 'node:module';
import { platform } from 'node:os';

/**
 * Map Node's `process.platform` value (linux/darwin/win32) to the
 * directory name used under `verification/`. Lets the caller's path
 * default to the right OS subfolder without hardcoding.
 */
export function osDir(p = platform()) {
  if (p === 'darwin') return 'macos';
  if (p === 'win32') return 'windows';
  return 'linux'; // linux + anything unknown
}

/**
 * Try to load the binary RVF backend (@ruvector/rvf-node) from the
 * caller's node_modules. Returns the RvfDatabase class or null if the
 * package isn't installed — callers fall back to JSONL.
 */
function loadRvfNode(probeRoots) {
  const expanded = [
    ...probeRoots,
    ...probeRoots.flatMap(r => [
      join(r, 'v3/@claude-flow/cli'),
      join(r, 'v3/@claude-flow/memory'),
    ]),
  ];
  for (const root of expanded) {
    try {
      const req = createRequire(join(root, 'noop.js'));
      const mod = req('@ruvector/rvf-node');
      if (mod && mod.RvfDatabase) return mod.RvfDatabase;
    } catch { /* try next */ }
  }
  return null;
}

// ─── ed25519 lazy load ─────────────────────────────────────────────
// Locate @noble/ed25519 from the caller's project (it lives in their
// node_modules, not bundled with this script). We probe a few likely
// install roots so the toolkit works in ruflo's monorepo layout *and*
// a user's flat node_modules.
function loadEd25519(probeRoots) {
  // Expand caller-supplied roots with workspace-package locations so
  // pnpm's isolated layout (where transitive deps don't hoist to the
  // workspace root) still resolves @noble/ed25519. Callers don't need
  // to know about this — the function just probes more places.
  const expanded = [
    ...probeRoots,
    ...probeRoots.flatMap(r => [
      join(r, 'v3/@claude-flow/cli'),
      join(r, 'v3/@claude-flow/plugin-agent-federation'),
    ]),
  ];
  let lastErr;
  for (const root of expanded) {
    try {
      const req = createRequire(join(root, 'noop.js'));
      const ed = req('@noble/ed25519');
      ed.etc.sha512Sync = (...m) => {
        const h = createHash('sha512');
        for (const x of m) h.update(x);
        return h.digest();
      };
      return ed;
    } catch (e) { lastErr = e; }
  }
  throw new Error(
    "Could not locate '@noble/ed25519'. Install it in your project " +
    "(npm i @noble/ed25519) or pass a node_modules root via the " +
    "WITNESS_ED25519_ROOT env var. Probed: " + expanded.join(', ') +
    ". Last error: " + (lastErr?.message ?? '?')
  );
}

// ─── manifest helpers ─────────────────────────────────────────────
export function fileSha256(absPath) {
  return createHash('sha256').update(readFileSync(absPath)).digest('hex');
}

export function fileContains(absPath, marker) {
  return readFileSync(absPath, 'utf8').includes(marker);
}

export function refreshFix(repoRoot, fix) {
  const abs = join(repoRoot, fix.file);
  if (!existsSync(abs)) {
    return { ...fix, sha256: fix.sha256 ?? '', markerVerified: false, _missing: true };
  }
  const sha256 = fileSha256(abs);
  const markerVerified = fileContains(abs, fix.marker);
  return { id: fix.id, desc: fix.desc, file: fix.file, sha256, marker: fix.marker, markerVerified };
}

// ─── regenerate ───────────────────────────────────────────────────
/**
 * Regenerate a signed witness manifest.
 *
 * @param {object} opts
 * @param {string} opts.repoRoot       Absolute path to the project root.
 * @param {string} opts.manifestPath   Where to write verification.md.json.
 * @param {Array}  opts.newFixes       New fix entries to register.
 * @param {object} [opts.releases]     Map of pkg → version for the manifest.
 * @param {string[]} [opts.ed25519Roots] Probe roots for @noble/ed25519.
 * @returns {{witness: object, summary: string}}
 */
export function regenerate(opts) {
  const { repoRoot, manifestPath, newFixes = [], releases = {}, ed25519Roots = [] } = opts;
  const ed = loadEd25519(ed25519Roots.length ? ed25519Roots : [repoRoot, join(repoRoot, 'v3')]);

  const existing = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf8')) : null;
  const oldFixes = existing?.manifest?.fixes ?? [];
  const oldIds = new Set(oldFixes.map(f => f.id));

  const merged = [
    ...oldFixes.map(f => refreshFix(repoRoot, f)),
    ...newFixes.filter(f => !oldIds.has(f.id)).map(f => refreshFix(repoRoot, f)),
  ];

  const gitCommit = execSync('git rev-parse HEAD', { cwd: repoRoot }).toString().trim();
  const branch = execSync('git rev-parse --abbrev-ref HEAD', { cwd: repoRoot }).toString().trim();
  const issuedAt = new Date().toISOString();

  const verifiedCount = merged.filter(f => f.markerVerified).length;
  const missingCount = merged.filter(f => f._missing).length;

  const manifest = {
    schema: existing?.manifest?.schema ?? 'ruflo-witness/v1',
    issuedAt,
    gitCommit,
    branch,
    os: osDir(),
    releases,
    summary: { totalFixes: merged.length, verified: verifiedCount, missing: missingCount },
    fixes: merged.map(f => { const { _missing, ...c } = f; return c; }),
  };

  const manifestCanonical = JSON.stringify(manifest);
  const manifestHash = createHash('sha256').update(manifestCanonical).digest('hex');
  const seed = createHash('sha256').update(gitCommit + ':ruflo-witness/v1').digest();
  const publicKey = ed.getPublicKey(seed);
  const signature = ed.sign(Buffer.from(manifestHash, 'hex'), seed);

  const witness = {
    manifest,
    integrity: {
      manifestHashAlgo: 'sha256',
      manifestHash,
      signatureAlgo: 'ed25519',
      publicKey: Buffer.from(publicKey).toString('hex'),
      signature: Buffer.from(signature).toString('hex'),
      seedDerivation: "sha256(gitCommit + ':ruflo-witness/v1')",
    },
  };

  const newIds = newFixes.filter(f => !oldIds.has(f.id)).map(f => f.id);
  const summary =
    `gitCommit:    ${gitCommit.slice(0,12)}…\n` +
    `branch:       ${branch}\n` +
    `issuedAt:     ${issuedAt}\n` +
    `total fixes:  ${merged.length}  (was ${oldFixes.length})\n` +
    `verified:     ${verifiedCount}\n` +
    `missing:      ${missingCount}\n` +
    `new entries:  ${newIds.join(', ') || '(none)'}\n` +
    `releases:     ${JSON.stringify(releases)}`;

  return { witness, summary, manifest, gitCommit, manifestHash };
}

// ─── temporal history ─────────────────────────────────────────────
/**
 * Append a compact snapshot of `manifest` to a JSONL history file
 * (one entry per line — git-diff-friendly, append-cheap).
 *
 * The history lives inside an RVF-style cognitive container layout
 * (`verification/<os>/history.jsonl`). RVF's binary format optimises
 * for vector similarity search; the witness use case is structured
 * key-value retrieval (snapshot N's commit + fixes), so JSONL is the
 * better format inside the container. The container concept — per-OS
 * folder bundling manifest + history + metadata — is what we adopt
 * from RVF, not the file format itself.
 *
 * @param {string} historyPath  Path to history.jsonl.
 * @param {object} manifest     The manifest object just signed.
 * @param {string} manifestHash The signed hash (for fast lookup).
 */
export function appendHistory(historyPath, manifest, manifestHash) {
  const fixesIndex = {};
  for (const f of manifest.fixes) {
    fixesIndex[f.id] = { sha256: f.sha256, markerVerified: f.markerVerified };
  }
  const entry = {
    v: 1,
    commit: manifest.gitCommit,
    issuedAt: manifest.issuedAt,
    branch: manifest.branch,
    os: manifest.os,
    manifestHash,
    summary: manifest.summary,
    fixes: fixesIndex,
  };
  appendFileSync(historyPath, JSON.stringify(entry) + '\n');
  return entry;
}

/**
 * Load the JSONL history into memory (chronological order).
 */
export function loadHistory(historyPath) {
  if (!existsSync(historyPath)) return [];
  const lines = readFileSync(historyPath, 'utf8').split('\n').filter(Boolean);
  return lines.map(l => JSON.parse(l));
}

/**
 * For each fix that is currently `regressed` (markerVerified=false in the
 * latest entry), walk backwards to find the most recent entry where it
 * was `pass` (markerVerified=true). The next entry after that is where
 * the regression was introduced.
 *
 * @returns {Array<{id, lastPassCommit, regressedAtCommit, atIssuedAt}>}
 */
export function findRegressionIntroductions(history) {
  if (history.length === 0) return [];
  const latest = history[history.length - 1];
  const out = [];
  for (const [id, state] of Object.entries(latest.fixes)) {
    if (state.markerVerified) continue;
    let lastPass = null;
    let regressedAt = latest;
    for (let i = history.length - 2; i >= 0; i--) {
      const e = history[i];
      const s = e.fixes[id];
      if (s && s.markerVerified) { lastPass = e; break; }
      regressedAt = e;
    }
    out.push({
      id,
      lastPassCommit: lastPass?.commit ?? null,
      lastPassIssuedAt: lastPass?.issuedAt ?? null,
      regressedAtCommit: regressedAt.commit,
      regressedAtIssuedAt: regressedAt.issuedAt,
    });
  }
  return out;
}

/**
 * Build a status timeline for a single fix across all history entries.
 *
 * @returns {Array<{commit, issuedAt, status}>}
 *   status ∈ { 'pass', 'regressed', 'absent' }
 */
export function fixTimeline(history, fixId) {
  return history.map(e => ({
    commit: e.commit,
    issuedAt: e.issuedAt,
    status: e.fixes[fixId]
      ? (e.fixes[fixId].markerVerified ? 'pass' : 'regressed')
      : 'absent',
  }));
}

/**
 * Compare the latest entry to the previous entry and report transitions.
 *
 * @returns {{newlyRegressed: string[], newlyPassing: string[], added: string[], removed: string[]}}
 */
export function diffLatest(history) {
  if (history.length < 2) return { newlyRegressed: [], newlyPassing: [], added: [], removed: [] };
  const [prev, curr] = [history[history.length - 2], history[history.length - 1]];
  const newlyRegressed = [];
  const newlyPassing = [];
  const added = [];
  const removed = [];
  for (const id of Object.keys(curr.fixes)) {
    if (!(id in prev.fixes)) added.push(id);
    else if (prev.fixes[id].markerVerified && !curr.fixes[id].markerVerified) newlyRegressed.push(id);
    else if (!prev.fixes[id].markerVerified && curr.fixes[id].markerVerified) newlyPassing.push(id);
  }
  for (const id of Object.keys(prev.fixes)) {
    if (!(id in curr.fixes)) removed.push(id);
  }
  return { newlyRegressed, newlyPassing, added, removed };
}

#!/usr/bin/env node
/**
 * Performance verification — benchmark key user-visible capabilities and
 * append per-OS measurements to verification/<os>/performance.jsonl.
 *
 * Each entry is one capability×measurement at a single git commit. The
 * file is JSONL so a regression in install-time or CLI-startup gets
 * caught the same way `verify.mjs` catches a marker disappearing — by
 * comparing to the running baseline (median of last N) and flagging
 * deltas that exceed a threshold.
 *
 * Capabilities tracked
 * ────────────────────
 *   install_pack          how long `pnpm pack @claude-flow/memory` takes
 *   install_no_optional   how long `npm install <tarball> --omit=optional` takes
 *   memory_load           how long `import('@claude-flow/memory')` takes
 *   memory_round_trip     store + get on the auto-selected backend
 *   witness_verify        how long `verify.mjs --manifest` takes
 *
 * Each measurement records:
 *   { v, commit, issuedAt, os, capability, durationMs, metadata }
 *
 * Usage:
 *   node plugins/ruflo-core/scripts/witness/perf.mjs \
 *     --output verification/<os>/performance.jsonl
 *
 *   --capabilities install_pack,memory_load   # subset
 *   --baseline                                # compare against last 5 entries
 *   --json                                    # machine-readable output
 */

import { writeFileSync, appendFileSync, readFileSync, existsSync, mkdtempSync, rmSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { tmpdir } from 'node:os';
import { execFileSync, spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { osDir } from './lib.mjs';

const __dirname = dirname(fileURLToPath(import.meta.url));

const args = parseArgs(process.argv.slice(2));
if (args.help) {
  console.log(readFileSync(new URL(import.meta.url), 'utf8').split('\n').filter(l => l.startsWith(' *')).map(l => l.slice(3)).join('\n'));
  process.exit(0);
}

const REPO_ROOT = resolve(args.root ?? process.cwd());
const OUTPUT = args.output ? resolve(args.output) : join(REPO_ROOT, 'verification', osDir(), 'performance.jsonl');
const ASJSON = !!args.json;
const COMPARE_BASELINE = !!args.baseline;
const ENABLED = (args.capabilities ?? 'install_pack,install_no_optional,memory_load,memory_round_trip,witness_verify').split(',').map(s => s.trim()).filter(Boolean);

const gitCommit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: REPO_ROOT }).toString().trim();
const issuedAt = new Date().toISOString();
const os = osDir();

// ─── benchmark runners ─────────────────────────────────────────
const runners = {
  install_pack: () => bench(() => {
    // execFileSync with array args prevents shell injection (CWE-78).
    execFileSync('pnpm', ['pack', '--pack-destination', tmpdir()], {
      cwd: join(REPO_ROOT, 'v3/@claude-flow/memory'),
      stdio: 'pipe',
    });
  }),

  install_no_optional: () => {
    const dir = mkdtempSync(join(tmpdir(), 'perf-install-'));
    const tarball = execFileSync('pnpm', ['pack', '--pack-destination', dir], {
      cwd: join(REPO_ROOT, 'v3/@claude-flow/memory'),
      stdio: 'pipe',
    }).toString().trim().split('\n').filter(l => l.endsWith('.tgz')).pop();
    if (!tarball) throw new Error('pnpm pack produced no tarball');
    execFileSync('npm', ['init', '-y'], { cwd: dir, stdio: 'pipe' });
    execFileSync('npm', ['pkg', 'set', 'type=module'], { cwd: dir, stdio: 'pipe' });
    const ms = bench(() => {
      // Pass tarball path as a discrete argument — no shell quoting needed.
      execFileSync('npm', ['install', tarball, '--omit=optional', '--no-audit', '--no-fund'], { cwd: dir, stdio: 'pipe' });
    });
    rmSync(dir, { recursive: true, force: true });
    return ms;
  },

  memory_load: () => {
    return bench(() => {
      // Spawn a fresh node process so import is truly cold.
      spawnSync(process.execPath, ['-e', "import('@claude-flow/memory').then(()=>{}).catch(e=>{process.exit(1)})"], {
        cwd: REPO_ROOT,
        stdio: 'pipe',
      });
    });
  },

  memory_round_trip: () => {
    const dbPath = join(tmpdir(), `perf-mem-${Date.now()}.db`);
    const ms = bench(() => {
      const r = spawnSync(process.execPath, ['-e', `
        const m = await import('@claude-flow/memory');
        const db = await m.createDatabase('${dbPath}', { provider: 'auto' });
        await db.initialize();
        const ts = Date.now();
        await db.store({ id: 'p1', key: 'k', content: 'v', type: 'episodic', namespace: 'd',
          tags: [], metadata: {}, accessLevel: 'private',
          createdAt: ts, updatedAt: ts, version: 1, references: [], accessCount: 0, lastAccessedAt: ts });
        await db.get('p1');
        await db.shutdown?.();
      `], { cwd: REPO_ROOT, stdio: 'pipe' });
      if (r.status !== 0) throw new Error('memory_round_trip failed: ' + r.stderr?.toString());
    });
    try { rmSync(dbPath, { force: true }); } catch { /* */ }
    return ms;
  },

  witness_verify: () => {
    const manifest = join(REPO_ROOT, 'verification', os, 'manifest.md.json');
    if (!existsSync(manifest)) return null;
    return bench(() => {
      // Use execFileSync so paths with spaces or special chars are safe (CWE-78).
      execFileSync(process.execPath, [join(__dirname, 'verify.mjs'), '--manifest', manifest, '--json'], {
        cwd: REPO_ROOT, stdio: 'pipe',
      });
    });
  },
};

// ─── bench helper ───────────────────────────────────────────────
function bench(fn) {
  const start = process.hrtime.bigint();
  try { fn(); } catch (e) {
    return { error: e.message ?? String(e), durationMs: null };
  }
  const ms = Number((process.hrtime.bigint() - start) / 1_000_000n);
  return { durationMs: ms };
}

// ─── baseline comparison ────────────────────────────────────────
function loadBaseline(capability) {
  if (!existsSync(OUTPUT)) return null;
  const lines = readFileSync(OUTPUT, 'utf8').split('\n').filter(Boolean);
  const recent = lines.map(l => JSON.parse(l)).filter(e => e.capability === capability && e.durationMs != null).slice(-5);
  if (recent.length < 3) return null;
  const sorted = [...recent].sort((a, b) => a.durationMs - b.durationMs);
  return sorted[Math.floor(sorted.length / 2)].durationMs; // median
}

// ─── run ─────────────────────────────────────────────────────────
const results = [];
for (const cap of ENABLED) {
  if (!runners[cap]) {
    if (!ASJSON) console.error(`unknown capability: ${cap}`);
    continue;
  }
  if (!ASJSON) console.error(`benchmarking: ${cap}`);
  const r = runners[cap]();
  if (r === null) continue; // skipped
  const baseline = COMPARE_BASELINE ? loadBaseline(cap) : null;
  const entry = {
    v: 1,
    commit: gitCommit,
    issuedAt,
    os,
    capability: cap,
    ...r,
    ...(baseline != null && r.durationMs != null
      ? { baselineMs: baseline, deltaPct: Math.round(((r.durationMs - baseline) / baseline) * 100) }
      : {}),
  };
  results.push(entry);
  appendFileSync(OUTPUT, JSON.stringify(entry) + '\n');
}

// ─── report ─────────────────────────────────────────────────────
if (ASJSON) {
  console.log(JSON.stringify({ commit: gitCommit, os, results }, null, 2));
} else {
  console.log(`\nperf summary (commit=${gitCommit.slice(0, 12)}, os=${os})`);
  console.log('─'.repeat(60));
  for (const r of results) {
    const dur = r.durationMs != null ? `${r.durationMs}ms`.padStart(10) : 'error'.padStart(10);
    const delta = r.deltaPct != null ? ` (${r.deltaPct >= 0 ? '+' : ''}${r.deltaPct}% vs baseline)` : '';
    const err = r.error ? `  ERROR: ${r.error}` : '';
    console.log(`  ${r.capability.padEnd(22)} ${dur}${delta}${err}`);
  }
  console.log(`\nappended: ${OUTPUT}`);
}

const failed = results.filter(r => r.error);
process.exit(failed.length > 0 ? 1 : 0);

// ─── arg parser ─────────────────────────────────────────────────
function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--baseline' || a === '--json' || a === '--help') { out[a.slice(2)] = true; continue; }
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else { out[key] = true; }
    }
  }
  return out;
}

#!/usr/bin/env node
/**
 * Regenerate a signed witness manifest with temporal history (ADR-103).
 *
 * Project-agnostic CLI wrapper around `lib.mjs`. Works in any repo that
 * has @noble/ed25519 installed somewhere (this script probes common roots).
 *
 * Usage:
 *   node regen.mjs --manifest <path> [--history <path>] [--fixes <json>] [--dry-run]
 *
 * Options:
 *   --manifest <path>   Where to write the signed manifest (verification.md.json).
 *   --history  <path>   JSONL history file to append a snapshot (omit to skip).
 *   --fixes    <path>   JSON file with NEW_FIXES to register on this regen.
 *                       Format: { "fixes": [ { "id", "desc", "file", "marker" }, ... ] }
 *   --releases <path>   Optional JSON file mapping pkg → version for the manifest.
 *   --root     <path>   Project root (defaults to cwd).
 *   --dry-run           Print summary without writing.
 *
 * Examples:
 *   # Refresh existing manifest (no new fixes)
 *   node regen.mjs --manifest verification.md.json --history verification-history.jsonl
 *
 *   # Add new fixes from a config file
 *   node regen.mjs --manifest verification.md.json --history verification-history.jsonl \
 *                  --fixes new-fixes.json --releases releases.json
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { resolve } from 'node:path';
import { regenerate, appendHistory } from './lib.mjs';

const args = parseArgs(process.argv.slice(2));
if (!args.manifest) {
  console.error('Error: --manifest <path> is required');
  console.error('Run with --help for usage.');
  process.exit(2);
}
if (args.help) {
  console.log(readFileSync(new URL(import.meta.url), 'utf8').split('\n').filter(l => l.startsWith(' *')).map(l => l.slice(3)).join('\n'));
  process.exit(0);
}

const repoRoot = resolve(args.root ?? process.cwd());
const manifestPath = resolve(args.manifest);
const historyPath = args.history ? resolve(args.history) : null;

const newFixes = args.fixes
  ? JSON.parse(readFileSync(resolve(args.fixes), 'utf8')).fixes ?? []
  : [];

const releases = args.releases
  ? JSON.parse(readFileSync(resolve(args.releases), 'utf8'))
  : {};

const result = regenerate({
  repoRoot,
  manifestPath,
  newFixes,
  releases,
  ed25519Roots: [repoRoot, resolve(repoRoot, 'v3')],
});

console.log(`witness regen summary\n─────────────────────`);
console.log(result.summary);

if (args['dry-run']) {
  console.log('\n(dry-run — manifest NOT written)');
  process.exit(0);
}

writeFileSync(manifestPath, JSON.stringify(result.witness, null, 2));
console.log(`\nwritten: ${manifestPath}`);

if (historyPath) {
  appendHistory(historyPath, result.witness.manifest, result.manifestHash);
  console.log(`appended: ${historyPath}`);
}

// ─── tiny arg parser (no deps) ────────────────────────────────────
function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--dry-run' || a === '--help') { out[a.slice(2)] = true; continue; }
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else { out[key] = true; }
    }
  }
  return out;
}

#!/usr/bin/env node
/**
 * Verify a signed witness manifest against the live tree (ADR-103).
 *
 * Project-agnostic — works without ruflo CLI being installed.
 *
 * Usage:
 *   node verify.mjs --manifest <path> [--root <path>] [--source-only] [--json]
 *
 * Exit codes:
 *   0  — signature valid + all fixes pass or drift (marker present)
 *   1  — signature invalid OR any fix regressed/missing (real failure)
 *   2  — bad arguments / file not found OR precondition not met
 *        (e.g. dist files not built during full-tree verification).
 *        Issue #1880: scheduled runners use this to distinguish a
 *        "needs install+build" environment from a real verification
 *        failure, so we stop filing recurring issues on every cron run.
 */

import { readFileSync, existsSync } from 'node:fs';
import { resolve, join } from 'node:path';
import {
  createHash,
  createPrivateKey,
  createPublicKey,
  verify as verifyEd25519,
} from 'node:crypto';
import { fileSha256, fileContains } from './lib.mjs';

const args = parseArgs(process.argv.slice(2));
if (!args.manifest) { console.error('--manifest <path> required'); process.exit(2); }

const manifestPath = resolve(args.manifest);
if (!existsSync(manifestPath)) { console.error(`not found: ${manifestPath}`); process.exit(2); }

const repoRoot = resolve(args.root ?? process.cwd());
const asJson = !!args.json;
const sourceOnly = !!args['source-only'];

const witness = JSON.parse(readFileSync(manifestPath, 'utf8'));

// ─── signature ────────────────────────────────────────────────────
const sig = verifySignature(witness);

// ─── per-fix marker check ─────────────────────────────────────────
const allFixes = witness.manifest.fixes;
const selectedFixes = sourceOnly
  ? allFixes.filter((fix) => !isGeneratedDistPath(fix.file))
  : allFixes;
const skippedGenerated = allFixes.length - selectedFixes.length;

if (sourceOnly && selectedFixes.length === 0) {
  const result = {
    ok: false,
    scope: 'source-only',
    precondition: 'no-source-entries',
    signature: sig,
  };
  if (asJson) console.log(JSON.stringify(result, null, 2));
  else console.error('verify.mjs: manifest contains no source entries to verify');
  process.exit(2);
}

const fileResults = selectedFixes.map((fix) => {
  const installed = join(repoRoot, fix.file);
  if (!existsSync(installed)) {
    return { ...fix, status: 'missing', sha256Match: false, markerPresent: false };
  }
  const localSha256 = fileSha256(installed);
  const markerPresent = fileContains(installed, fix.marker);
  const sha256Match = localSha256 === fix.sha256;
  const status = sha256Match && markerPresent ? 'pass'
              : (markerPresent ? 'drift' : 'regressed');
  return { ...fix, status, sha256Match, markerPresent, localSha256 };
});

const summary = {
  pass: fileResults.filter(r => r.status === 'pass').length,
  drift: fileResults.filter(r => r.status === 'drift').length,
  regressed: fileResults.filter(r => r.status === 'regressed').length,
  missing: fileResults.filter(r => r.status === 'missing').length,
  skippedGenerated,
};

// Issue #1880 / #2528 — heuristic: if the only missing entries are
// generated `/dist/` artifacts and no marker regressed, the checkout was
// source-only (dependencies may be installed, but no build ran). That's a
// precondition failure, not a regression. Source-file drift is still
// reported in the JSON summary, but the operator action is the same:
// install + build before verifying the dist-layer witness entries.
const allMissing = fileResults.length > 0
                && summary.missing === fileResults.length;
const missingResults = fileResults.filter(r => r.status === 'missing');
const missingOnlyDist = missingResults.length > 0
  && missingResults.every(r => isGeneratedDistPath(r.file));
const referencesDist = fileResults.some(r => isGeneratedDistPath(r.file));
if (!sourceOnly && ((allMissing && referencesDist) || (missingOnlyDist && summary.regressed === 0))) {
  if (asJson) {
    console.log(JSON.stringify(
      { ok: false, scope: 'full', precondition: 'dist-not-built', signature: sig, summary },
      null, 2
    ));
  } else {
    console.error(
      `verify.mjs: every manifest entry is missing and the manifest references\n` +
      `dist/ artifacts. The checkout appears to be source-only (no build run).\n` +
      `\n` +
      `Fix: from the repo root, run \`npm ci && npm run build\` (or the\n` +
      `equivalent for the workspaces witness markers reference) before\n` +
      `invoking this script. See #1880 for the full diagnosis.`
    );
  }
  process.exit(2);
}

const ok = sig.signatureValid && sig.manifestHashOk && sig.publicKeyReproducible
        && summary.regressed === 0 && summary.missing === 0;

if (asJson) {
  console.log(JSON.stringify(
    { ok, scope: sourceOnly ? 'source-only' : 'full', signature: sig, summary, results: fileResults },
    null,
    2
  ));
} else {
  console.log(`Verification scope: ${sourceOnly ? 'source-only' : 'full'}`);
  console.log('Manifest signature:');
  console.log(`  hash matches:                    ${sig.manifestHashOk ? 'yes' : 'NO'}`);
  console.log(`  public key reproducible:         ${sig.publicKeyReproducible ? 'yes' : 'NO'}`);
  console.log(`  Ed25519 signature valid:         ${sig.signatureValid ? 'yes' : 'NO'}`);
  console.log('');
  console.log(`Summary: pass=${summary.pass} drift=${summary.drift} regressed=${summary.regressed} missing=${summary.missing} skipped-generated=${summary.skippedGenerated}`);
  if (summary.regressed > 0) {
    console.log('\nRegressed:');
    for (const r of fileResults.filter(r => r.status === 'regressed')) {
      console.log(`  ${r.id}  marker missing in ${r.file}`);
    }
  }
  if (summary.missing > 0) {
    console.log('\nMissing files:');
    for (const r of fileResults.filter(r => r.status === 'missing')) {
      console.log(`  ${r.id}  ${r.file}`);
    }
  }
}

process.exit(ok ? 0 : 1);

// ─── ed25519 helpers ─────────────────────────────────────────────
function verifySignature(witness) {
  try {
    const recomputed = createHash('sha256').update(JSON.stringify(witness.manifest)).digest('hex');
    const manifestHashOk = recomputed === witness.integrity.manifestHash;
    const seed = createHash('sha256')
      .update(witness.manifest.gitCommit + ':ruflo-witness/v1')
      .digest();

    // RFC 8410 DER wrappers let Node/OpenSSL derive and verify Ed25519 keys
    // without a package install. The witness format remains byte-compatible
    // with manifests produced by @noble/ed25519.
    const privateKey = createPrivateKey({
      key: Buffer.concat([
        Buffer.from('302e020100300506032b657004220420', 'hex'),
        seed,
      ]),
      format: 'der',
      type: 'pkcs8',
    });
    const reproducedKey = createPublicKey(privateKey)
      .export({ format: 'der', type: 'spki' })
      .subarray(-32);
    const publicKeyReproducible =
      reproducedKey.toString('hex') === witness.integrity.publicKey;

    const declaredKey = createPublicKey({
      key: Buffer.concat([
        Buffer.from('302a300506032b6570032100', 'hex'),
        Buffer.from(witness.integrity.publicKey, 'hex'),
      ]),
      format: 'der',
      type: 'spki',
    });
    const signatureValid = verifyEd25519(
      null,
      Buffer.from(witness.integrity.manifestHash, 'hex'),
      declaredKey,
      Buffer.from(witness.integrity.signature, 'hex'),
    );
    return { manifestHashOk, publicKeyReproducible, signatureValid, verifier: 'node:crypto' };
  } catch (error) {
    return {
      manifestHashOk: false,
      publicKeyReproducible: false,
      signatureValid: false,
      verifier: 'node:crypto',
      reason: 'signature-verification-error',
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

function isGeneratedDistPath(file) {
  return typeof file === 'string' && file.split(/[\\/]/).includes('dist');
}

function parseArgs(argv) {
  const out = {};
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i];
    if (a === '--json' || a === '--help') { out[a.slice(2)] = true; continue; }
    if (a.startsWith('--')) {
      const key = a.slice(2);
      const next = argv[i + 1];
      if (next && !next.startsWith('--')) { out[key] = next; i++; }
      else { out[key] = true; }
    }
  }
  return out;
}
